import Foundation
import ImmichAPI

/// Connection details for the stock Immich test server (see TestServer/ and scripts/test-server.sh).
///
/// Credentials are generated by TestServer/seed.py and kept in TestServer/.secrets/ (never committed).
/// Integration tests are skipped when the server or credentials aren't available.
enum TestServer {
    struct Account: Decodable { let email: String; let name: String; let password: String }
    struct Credentials: Decodable { let admin: Account; let user: Account }

    static let url = URL(string: ProcessInfo.processInfo.environment["DARKROOM_TEST_SERVER"] ?? "http://localhost:2283")!

    static var secretsDirectory: URL {
        if let dir = ProcessInfo.processInfo.environment["DARKROOM_TEST_SECRETS"] { return URL(fileURLWithPath: dir) }
        // Packages/DarkRoomKit/Tests/IntegrationTests/TestServer.swift -> repo root
        return URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appending(path: "TestServer/.secrets")
    }

    static let credentials: Credentials? = {
        guard let data = try? Data(contentsOf: secretsDirectory.appending(path: "credentials.json")) else { return nil }
        return try? JSONDecoder().decode(Credentials.self, from: data)
    }()

    /// Seeded asset ids by category (TestServer/.secrets/seed-result.json).
    static let seeded: [String: [String]] = {
        guard let data = try? Data(contentsOf: secretsDirectory.appending(path: "seed-result.json")) else { return [:] }
        return (try? JSONDecoder().decode([String: [String]].self, from: data)) ?? [:]
    }()

    static var isAvailable: Bool {
        guard credentials != nil else { return false }
        let semaphore = DispatchSemaphore(value: 0)
        nonisolated(unsafe) var ok = false
        var request = URLRequest(url: url.appending(path: "api/server/ping"))
        request.timeoutInterval = 3
        URLSession.shared.dataTask(with: request) { _, response, _ in
            ok = (response as? HTTPURLResponse)?.statusCode == 200
            semaphore.signal()
        }.resume()
        semaphore.wait()
        return ok
    }

    static func client(as account: KeyPath<Credentials, Account> = \.admin) async throws -> ImmichClient {
        let anonymous = ImmichClient(serverURL: url)
        let creds = credentials![keyPath: account]
        let login = try await anonymous.login(body: LoginCredentialDto(email: creds.email, password: creds.password))
        return anonymous.with(credential: .session(login.accessToken))
    }
}
